//! VFS-generated nodes (M8h): the procfs and devfs entries built by `vfs::init`.
//!
//! The nodes themselves are ordinary VNodes whose [`Backing::Generated`] names a
//! pseudo node id. This module owns their contents and the character-device
//! behaviour:
//!
//! - `/proc/self/status` and `/proc/uptime` are read-only files with size zero:
//!   every read asks this module for freshly generated bytes, so nothing is ever
//!   cached in the page cache and a later process state change is visible on the
//!   next read.
//! - `/dev/null` (1,3) always reads end-of-file and discards writes.
//! - `/dev/zero` (1,5) returns zero bytes forever and discards writes.
//!
//! The module never prints or allocates: its text is built into a stack buffer
//! owned by the read path.

use super::types::VNodeId as Id;
use super::types::{NodeKind as Kind, VfsError};
use super::vnode::{Backing, Table};

/// Pseudo node id of `/proc/self/status`.
pub(crate) const STATUS: u16 = 1;
/// Pseudo node id of `/proc/uptime`.
pub(crate) const UPTIME: u16 = 2;
/// Pseudo node id of `/dev/null`.
pub(crate) const NULL: u16 = 3;
/// Pseudo node id of `/dev/zero`.
pub(crate) const ZERO: u16 = 4;

/// Largest generated text one proc file needs (status is the long one).
const TEXT_MAX: usize = 192;

/// Build the generated namespace below `root`.
///
/// The two directories are read-only, so creation/unlink/rename/rmdir inside
/// them is refused by the VFS guards; the proc files are read-only as well, while
/// the character devices are technically writable (writes are discarded).
pub(crate) fn install(table: &mut Table, root: Id) -> Result<(), VfsError> {
    let proc = directory(table, root, b"proc")?;
    let self_dir = directory(table, proc, b"self")?;
    file(table, self_dir, b"status", STATUS)?;
    file(table, proc, b"uptime", UPTIME)?;
    let dev = directory(table, root, b"dev")?;
    character(table, dev, b"null", NULL, 3)?;
    character(table, dev, b"zero", ZERO, 5)?;
    Ok(())
}

/// Allocate one read-only generated directory.
fn directory(table: &mut Table, parent: Id, name: &[u8]) -> Result<Id, VfsError> {
    let id = table.alloc(Kind::Directory, parent, name, Backing::Ram)?;
    table.get_mut(id)?.read_only = true;
    Ok(id)
}

/// Allocate one read-only generated file (size zero, contents on demand).
fn file(table: &mut Table, parent: Id, name: &[u8], node: u16) -> Result<Id, VfsError> {
    let id = table.alloc(Kind::File, parent, name, Backing::Generated { node })?;
    let entry = table.get_mut(id)?;
    entry.read_only = true;
    entry.size = 0;
    Ok(id)
}

/// Allocate one character device (writable, size zero, dev 1,`minor`).
fn character(
    table: &mut Table,
    parent: Id,
    name: &[u8],
    node: u16,
    minor: u16,
) -> Result<Id, VfsError> {
    let id = table.alloc(Kind::CharDevice, parent, name, Backing::Generated { node })?;
    let entry = table.get_mut(id)?;
    entry.read_only = false;
    entry.size = 0;
    entry.dev_major = 1;
    entry.dev_minor = minor;
    Ok(id)
}

/// Serve one read of a generated node.
///
/// `offset` is a byte offset inside the generated text; past the end reads
/// return zero. Character devices ignore `offset` (null never has data, zero
/// always fills the buffer).
pub(crate) fn read(
    node: u16,
    kind: Kind,
    owner: u32,
    offset: u64,
    out: &mut [u8],
) -> Result<usize, VfsError> {
    if out.is_empty() {
        return Ok(0);
    }
    match (node, kind) {
        (NULL, Kind::CharDevice) => Ok(0),
        (ZERO, Kind::CharDevice) => {
            out.fill(0);
            Ok(out.len())
        }
        (STATUS, Kind::File) => {
            let mut text = [0u8; TEXT_MAX];
            let len = status(owner, &mut text);
            slice(&text[..len], offset, out)
        }
        (UPTIME, Kind::File) => {
            let mut text = [0u8; TEXT_MAX];
            let len = uptime(&mut text);
            slice(&text[..len], offset, out)
        }
        _ => Err(VfsError::NotSupported),
    }
}

/// Serve one write of a generated node: character devices discard it, proc
/// files are read-only (the VFS read-only check normally runs first).
pub(crate) fn write(kind: Kind, data: &[u8]) -> Result<usize, VfsError> {
    match kind {
        Kind::CharDevice => Ok(data.len()),
        _ => Err(VfsError::ReadOnly),
    }
}

/// Copy the `offset..` slice of `text` into `out`.
fn slice(text: &[u8], offset: u64, out: &mut [u8]) -> Result<usize, VfsError> {
    let start = usize::try_from(offset).unwrap_or(usize::MAX);
    if start >= text.len() {
        return Ok(0);
    }
    let len = (text.len() - start).min(out.len());
    out[..len].copy_from_slice(&text[start..start + len]);
    Ok(len)
}

/// Render `/proc/self/status` for `owner`, returning the byte length.
fn status(owner: u32, out: &mut [u8]) -> usize {
    let current_native = crate::process::current_process_id();
    let current_linux = crate::process::current_linux_pid();
    let is_current = current_native == Some(owner) || current_linux == Some(owner);
    // The compat open path passes the native process id today; report the Linux
    // pid for that case and fall back to the raw owner for anything else.
    let pid = if current_native == Some(owner) {
        current_linux.unwrap_or(owner)
    } else {
        owner
    };
    let ppid = if is_current {
        crate::process::parent_linux_pid().unwrap_or(0)
    } else {
        0
    };
    let state = if is_current {
        match crate::process::current().and_then(crate::process::process_state) {
            Some(crate::process::ProcessState::Blocked) => "S (sleeping)",
            Some(crate::process::ProcessState::Zombie) => "Z (zombie)",
            _ => "R (running)",
        }
    } else {
        "R (running)"
    };
    let mut len = 0;
    len = text(out, len, b"Name:\tlinux\n");
    len = text(out, len, b"State:\t");
    len = text(out, len, state.as_bytes());
    len = text(out, len, b"\n");
    len = text(out, len, b"Pid:\t");
    len = decimal(out, len, u64::from(pid));
    len = text(out, len, b"\n");
    len = text(out, len, b"PPid:\t");
    len = decimal(out, len, u64::from(ppid));
    len = text(out, len, b"\n");
    len = text(out, len, b"Uid:\t0\t0\t0\t0\n");
    len = text(out, len, b"Gid:\t0\t0\t0\t0\n");
    len = text(out, len, b"Threads:\t1\n");
    len
}

/// Render `/proc/uptime` (two identical fields: uptime and idle time).
fn uptime(out: &mut [u8]) -> usize {
    let ticks = crate::time::monotonic_ticks();
    let hz = u64::from(crate::time::tick_hz().max(1));
    let seconds = ticks / hz;
    let hundredths = (ticks % hz) * 100 / hz;
    let mut len = 0;
    len = decimal(out, len, seconds);
    len = text(out, len, b".");
    len = two_digits(out, len, hundredths as u32);
    len = text(out, len, b" ");
    len = decimal(out, len, seconds);
    len = text(out, len, b".");
    len = two_digits(out, len, hundredths as u32);
    len = text(out, len, b"\n");
    len
}

/// Append `value` at `at`, returning the new write position (clamped).
fn text(out: &mut [u8], at: usize, value: &[u8]) -> usize {
    let end = (at + value.len()).min(out.len());
    let len = end.saturating_sub(at);
    if len > 0 {
        out[at..end].copy_from_slice(&value[..len]);
    }
    end
}

/// Append an unsigned decimal number.
fn decimal(out: &mut [u8], at: usize, mut value: u64) -> usize {
    let mut digits = [0u8; 20];
    let mut len = 0;
    loop {
        digits[len] = b'0' + (value % 10) as u8;
        len += 1;
        value /= 10;
        if value == 0 {
            break;
        }
    }
    let mut at = at;
    for index in (0..len).rev() {
        at = text(out, at, &digits[index..=index]);
    }
    at
}

/// Append exactly two decimal digits (`00..=99`).
fn two_digits(out: &mut [u8], at: usize, value: u32) -> usize {
    let tens = b'0' + ((value / 10) % 10) as u8;
    let units = b'0' + (value % 10) as u8;
    let at = text(out, at, &[tens]);
    text(out, at, &[units])
}
